It requires `react-hook-form` registration, which makes it cumbersome for just a simple select inside a table row.
I'll just use a plain HTML `<select>` with Tailwind classes, or create a small component. Using a native `<select>` is perfectly fine and avoids react-hook-form boilerplate.

Let's create `update-user-role.tsx`:
```tsx
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { useNotifications } from '@/components/ui/notifications';
import { useUser } from '@/lib/auth';
import { User } from '@/types/api';

import { useUpdateUserRole } from '../api/update-user-role';

type UpdateUserRoleProps = {
  user: User;
};

const ROLES = [
  { label: 'Admin', value: 'ADMIN' as const },
  { label: 'User', value: 'USER' as const },
];

export const UpdateUserRole = ({ user }: UpdateUserRoleProps) => {
  const userQuery = useUser();
  const { addNotification } = useNotifications();
  const updateUserRoleMutation = useUpdateUserRole({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Role Updated',
        });
      },
    },
  });

  const [role, setRole] = useState(user.role);

  // Only allow changing if current user is admin
  if (userQuery.data?.role !== 'ADMIN') {
    return <span className="capitalize">{role}</span>;
  }

  const handleRoleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRole = e.target.value as 'ADMIN' | 'USER';
    setRole(newRole);
    updateUserRoleMutation.mutate({
      userId: user.id,
      data: { role: newRole },
    });
  };

  return (
    <select
      value={role}
      onChange={handleRoleChange}
      className="rounded-md border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:ring-blue-500"
      disabled={updateUserRoleMutation.isPending}
    >
      {ROLES.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
};
```
Wait, `user.role` might be undefined initially if the mutation hasn't finished, but optimistic update is fine. If it fails, the query refetch will revert it. That's acceptable for this scope.

