Here are the changes required to implement the admin role update functionality:

### 1. Add the Mutation Hook (`update-user-role.ts`)
Creates the API call and handles the success state (query invalidation and success notification).

**`apps/react-vite/src/features/users/api/update-user-role.ts`**
```tsx
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { useNotifications } from '@/components/ui/notifications';
import { MutationConfig } from '@/lib/react-query';

import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export const updateUserRole = ({
  userId,
  data,
}: {
  userId: string;
  data: UpdateUserRoleInput;
}) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    ...restConfig,
    mutationFn: updateUserRole,
    onSuccess: (...args) => {
      addNotification({
        type: 'success',
        title: 'Role Updated',
      });
      queryClient.invalidateQueries({
        queryKey: getUsersQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
  });
};
```

### 2. Add API to the Mock Server (`mock-server.ts`)
Adds the corresponding handler to simulate the backend `PATCH /users/:userId/role` endpoint.

**`apps/react-vite/src/testing/mocks/handlers/users.ts`** (Added at the end of `usersHandlers`)
```tsx
  http.patch(
    `${env.API_URL}/users/:userId/role`,
    async ({ params, request, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const userId = params.userId as string;
        requireAdmin(user);

        const data = (await request.json()) as { role: string };

        const result = db.user.update({
          where: {
            id: {
              equals: userId,
            },
            teamId: {
              equals: user?.teamId,
            },
          },
          data,
        });
        await persistDb('user');
        return HttpResponse.json(sanitizeUser(result));
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),
];
```

### 3. Create the Role Select Component (`update-user-role.tsx`)
Renders a dropdown for admins to select a new role. Non-admins will just see the role as plain text.

**`apps/react-vite/src/features/users/components/update-user-role.tsx`**
```tsx
import { useEffect, useState } from 'react';

import { useUser } from '@/lib/auth';
import { User } from '@/types/api';

import { useUpdateUserRole } from '../api/update-user-role';

type UpdateUserRoleProps = {
  user: User;
};

const ROLES = [
  { label: 'Admin', value: 'ADMIN' as const },
  { label: 'User', value: 'USER' as const },
];

export const UpdateUserRole = ({ user }: UpdateUserRoleProps) => {
  const userQuery = useUser();
  const updateUserRoleMutation = useUpdateUserRole();

  const [role, setRole] = useState(user.role);

  useEffect(() => {
    setRole(user.role);
  }, [user.role]);

  if (userQuery.data?.role !== 'ADMIN') {
    return <span className="capitalize">{role.toLowerCase()}</span>;
  }

  const handleRoleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRole = e.target.value as 'ADMIN' | 'USER';
    setRole(newRole);
    updateUserRoleMutation.mutate(
      {
        userId: user.id,
        data: { role: newRole },
      }
    );
  };

  return (
    <select
      value={role}
      onChange={handleRoleChange}
      className="rounded-md border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:ring-blue-500"
      disabled={updateUserRoleMutation.isPending}
    >
      {ROLES.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
};
```

### 4. Integrate into Users List (`users-list.tsx`)
Updates the table to render the `UpdateUserRole` component in the "Role" column.

**`apps/react-vite/src/features/users/components/users-list.tsx`**
